/**
 * EDK-side entity abstraction shared by every layer that touches
 * Elementum data — the entity-client (which produces them), the pull
 * pipeline (which writes them), and the agent (which authors and
 * reads them).
 *
 * Disambiguation note: jarvis defines a platform-wide `EntityType`
 * enum with ~150 values (every Elementum object has one — see
 * `jarvis/util/.../EntityType.java`). The EDK has its own much
 * coarser categorization with seven values. To avoid confusion, the
 * EDK types use the `Edk*` prefix (`EdkEntityType`, `EdkEntity`,
 * `WritableEdkEntityType`, `WritableEdkEntity`).
 *
 * An EDK entity is one of the top-level objects defined under
 * `elementum-entity-client/clients/<x>/`: agent, aspect (app),
 * automation, skill, user, group. Each is the canonical shape
 * for that thing as it exists in the user's Elementum org. The
 * `entityType` discriminator is added by the client function on the
 * way out (it's not on antman's wire) so downstream code can
 * dispatch on it without inspecting the import path or class name.
 *
 * Internal pipeline artifacts (deserializer ASTs, catalog snapshots
 * derived from entities, etc.) are NOT entities. They're scaffolding
 * the deserializer uses to convert wire shapes into source code.
 */
/**
 * Closed set of every EDK-level entity type the system knows about.
 * Adding a new client (e.g. once wolverine flows ship) means
 * extending this union and the `WritableEdkEntityType` filter below.
 */
export type EdkEntityType = "agent" | "approvalChain" | "aspect" | "automation" | "group" | "searchTable" | "skill" | "table" | "user";
/**
 * Entity types that have a `generated/` source representation. Users
 * and groups are discovery-only — they don't get pulled or authored —
 * so they're excluded here, which makes `pulledPath(root, user)` a
 * compile error rather than a runtime mistake.
 */
export type WritableEdkEntityType = Exclude<EdkEntityType, "user" | "group">;
export interface EdkEntity {
    readonly entityType: EdkEntityType;
    readonly id: string;
    readonly name: string;
}
export interface WritableEdkEntity extends EdkEntity {
    readonly entityType: WritableEdkEntityType;
}
/**
 * Platform-wide entity types from jarvis (SCREAMING_SNAKE), paired
 * 1:1 with their PascalCase `typeName` representation. Mirrors the
 * relevant slice of jarvis's `enum EntityType { APP_ASPECT("AspectApp"),
 * ELEMENT_ASPECT("AspectElement"), USER("User"), ... }` Java
 * enum — each enum value carries a typeName as an associated value.
 *
 * Today only the three values automation owners can take are listed
 * (`APP_ASPECT`, `ELEMENT_ASPECT`, `USER`). Extend as new clients
 * (B/agents, C/skills, D/flows) ship — the union derivations below
 * will widen automatically and any switches that don't handle the
 * new value become compile errors at the call site.
 *
 * Distinct from `EdkEntityType` (one layer up): EdkEntityType is the
 * EDK's coarse lowercase categorization (`"aspect"` covers both
 * APP_ASPECT and ELEMENT_ASPECT). Use this jarvis-projection layer
 * when wire fidelity matters; use EdkEntityType for filesystem
 * paths and writer discriminators where the granularity isn't.
 */
export declare const ENTITY_TYPES: {
    readonly APP_ASPECT: "AspectApp";
    readonly ELEMENT_ASPECT: "AspectElement";
    readonly USER: "User";
};
/**
 * The set of platform entity-type tokens (the keys of `ENTITY_TYPES`).
 *
 * Use as `EntityType` (the full set) when a value can be any owner
 * kind, or extract a per-use-case subset (e.g.
 * `AutomationOwnerType`) when narrowing matters.
 */
export type EntityType = keyof typeof ENTITY_TYPES;
/**
 * The set of PascalCase typeNames (the values of `ENTITY_TYPES`).
 * Mirrors what mobius emits in `__typename` and what the EDK
 * serializer-input shape carries on `owner.type`. 1:1 with
 * `EntityType`.
 */
export type TypeName = (typeof ENTITY_TYPES)[EntityType];
/**
 * Owner kinds an automation workflow accepts. Currently identical
 * to the full `EntityType` set, but expressed as an `Extract`
 * subset on purpose — when a future `EntityType` value (e.g.
 * `ASPECT_TASK`) gets added that automations can't own, this
 * subset stays narrow and the type system catches misuse.
 */
export type AutomationOwnerType = Extract<EntityType, "APP_ASPECT" | "ELEMENT_ASPECT" | "USER">;
/**
 * Canonical owner shape — what `Workflow.owner` and the
 * deserializer's normalized owner both carry. Generic on the
 * EntityType subset so per-entity callers can narrow:
 * `Owner<AutomationOwnerType>` for automations, `Owner<AgentOwnerType>`
 * (when defined) for agents, etc.
 */
export interface Owner<T extends EntityType = EntityType> {
    readonly id: string;
    readonly type: T;
}
